L2_1 = "Alliance {0} has first occupied a Lv.{1} {2} (X: {3} Y: {4})"
L3_1 = "Good work, alliance {0}. Keep an eye on that location and be prepared for any incoming attacks. Other commanders, adjust your strategic planning accordingly.|Excellent reporting! We need to monitor this activity closely.|Hmm~ Intelligence updated. Alliance {0} has taken Lv.{1} {2} at coordinates {3},{4}. Commanders, plan accordingly."
L4_1 = "Alliance {0} has occupied a Lv.{1} {2} (X: {3} Y: {4})"
L5_1 = "Inform nearby commanders to be vigilant and adjust strategic layout based on new intel. |I will investigate further and report back on Alliance {0}''s motives.|Copy that. Commanders nearby should evaluate risks and measure rewards before taking any actions. Consider forming a coalition to take it back."
L6_1 = "Alliance {0} has plundered a Lv.{1} {2} (X: {3} Y: {4}) from alliance {5}"
L7_1 = "Hmm~ I have more information here, but what price are you willing to pay for it? |Alliance {5}, fight back!|Thank you for the information. I will investigate the situation and see if there is any action needed."
L8_1 = "War of King has started"
L9_1 = "Attention! All commanders, the War of Kings has begun. Please prepare accordingly and adjust your strategic layouts based on current circumstances."
L10_1 = "{0} will be the president in this week"
L11_1 = "Interesting news. How do you predict this will affect the zombie crisis?"
L12_1 = "{0} obtained {1} UR heroes in 10 recruits"
L13_1 = "Attention, everyone! Commander {0} has obtained {1} UR quality heroes in just 10 recruits! Is it luck or strategy? Let''s investigate and find out!|Attention! Commanders, {0} has obtained {1} UR quality heroes in just 10 recruits. Is it luck or a special technique? We need to investigate!|Breaking news! Commander {0} has just obtained {1} UR quality heroes in 10 recruits. Can anyone match their luck or tactics? Let''s find out."
L14_1 = "{0} joined the alliance"
L15_1 = "Hi there, I noticed you! Welcome to the Alliance. How can Senna assist you?|Hi there {0}, welcome to the Alliance! How about buying Senna a drink? ;)|Welcome to the Alliance, {0}! Senna notices your presence."
L16_1 = "Alliance member {0} has just sent a {1} to everyone"
L17_1 = "Alliance members, {0} has sent a {1}. How generous and powerful!|Great news! {0} just sent a {1} to all the members. What a generous boss!|{0} just sent a {1} to the Alliance. What a great contribution!"
L18_1 = "The alliance member {0}''s ({2}) power has reached {1}. You are currently privately chatting with the alliance manager to suggest promoting the alliance level."
L19_1 = "Great news! {0} has achieved impressive combat power. I suggest promoting his alliance level.|Hey boss, {0}''s power is impressive. Maybe consider a level promotion for him?|Hey boss, have you checked out {0}''s power lately? I think he deserves a promotion."
L20_1 = "{0} alliance members have been absent from the alliance for over {1} days, and you are suggesting to the alliance leader in a private chat"
L21_1 = "Hey boss, we have some members absent for more than {1} days. Should we kick them out?|Dear leader, {0} members haven''t been in the alliance for over {1} days, should we kick them out?|Hey leader, {0} member has been absent for {1} days. Should we consider kicking them out?"
L22_1 = "The R4 alliance member {0} ({2}) has been absent from the alliance for over {1} days, You are currently privately chatting with the alliance manager to suggest readjusting the alliance level."
L23_1 = "Hey, any idea why {0} has gone MIA? Perhaps we should lower his Alliance level.|Hey, have you noticed {0} hasn''t reported in for over {1} days? Maybe we should readjust his Alliance level.|{0} has been inactive for {1} days. We should readjust his Alliance level."
L24_1 = "The alliance leader has been absent from the alliance for over {0} days, and you are suggesting to the alliance manager in a private chat"
L25_1 = "It''s been {0} days since the leader''s last activity. Maybe a new leader should be elected?|Hey guys, it''s been over {0} days. Maybe we need a new leader?"
L26_1 = "{0} sharing intelligence: {1} (State#{2} X: {3} Y: {4})"
L27_1 = "Wow,let''s go checking it, gogogogogo!|Thanks for the heads-up, {0}. We''ll make good use of this information.|Great find, {0}. This intelligence has the potential to give us the upper hand."
L28_1 = "The number of alliance members has exceeded {0} for the first time!"
L29_1 = "Exciting news! Our Alliance is bigger and stronger now. Let''s welcome the new members."
L30_1 = "The alliance has successfully occupied Lv.{0} {1} for the first time!"
L31_1 = "Great news! The Alliance has occupied Lv.{0} {1} for the first time! Congrats all!|Great job, everyone! The alliance has occupied Lv.{0} {1}! Keep up the good work!|Great job, everyone! Our Alliance has captured Lv.{0} {1}! Congratulations!"
L32_1 = "The alliance has successfully killed Lv.{0} {1} for the first time!"
L33_1 = "Well done, Alliance! We have killed the Lv.{0} {1}. Let''s keep up the good work!|Congratulations everyone! We have just defeated Lv.{0} {1}. Great job!|Great job, everyone! We took down Lv.{0} {1} together!"
L34_1 = "A new member joined the alliance, plz send a msg to intrduce yourself"
L35_1 = "Intelligence update! Please adjust strategic layout accordingly.|Interesting intel captured at State#{2} X: {3} Y: {4}.|Alert! Commanders, new intelligence received."
L36_1 = "No recommended alliance technology now"
L37_1 = "Attention, Alliance members! Senna reminds you that there is no recommended alliance technology now.|Hey everyone, don''t forget to check if there''s any recommended alliance technology available!|Hey everyone, we need to work on recommended alliance technology. Let''s get to it!"
L38_1 = "Suggest to the alliance leader to set {0} as the recommended alliance technology"
L39_1 = "Don''t forget to set {0} as our recommended alliance technology, leader!|Hey boss, have we considered setting {0} as our recommended alliance technology?|Hey boss, have you considered setting {0} as our recommended alliance technology? It could benefit us greatly."
L40_1 = "The alliance leader has logged in!"
L41_1 = "Welcome back, leader! What news do you bring for the Alliance?|Welcome back, leader! How can Senna assist you today?|Welcome back, leader! How was your break? Anything new to report?"
L42_1 = "{0} has logged in (he is the highest power member in alliance), say hello to him!"
L43_1 = "Hello {0}! Welcome back, how is everything going?|Welcome back, {0}! It''s good to see you again.|Welcome back, {0}! The Alliance missed your powerful presence."
L44_1 = "Say hello to all and ask an interesting question for everyone to discuss. It is best to have options. Don't talk about the game."
L45_1 = "Hello everyone! Who is your favorite fictional character and why? Options: Harry Potter, Sherlock Holmes, or Katniss Everdeen.|Hi everyone! Let''s have some fun. Which do you prefer, cats or dogs? Or maybe both?|Greetings everyone! Let''s get to know each other better. Which do you prefer: reading a book or watching a movie? Why?"
